// 1-bit bitmap fonts generated by tools/gen_font.py, and text drawing.
#pragma once

#include <cstdint>

#include "framebuffer.h"

namespace inkwake {

struct Glyph {
  uint32_t offset;  // into Font::bitmap; rows packed MSB first, no row padding
  uint8_t width;    // bitmap size; 0 = blank or missing glyph
  uint8_t height;
  int16_t left;     // bitmap x offset from the pen position
  int16_t top;      // bitmap top, from the baseline (negative = above)
  uint8_t advance;  // pen advance in pixels
};

struct Font {
  const uint8_t* bitmap;
  const Glyph* glyphs;  // glyphs[c - first] for first <= c <= last
  uint16_t first;
  uint16_t last;
  uint8_t ascent;  // cap height above the baseline, for layout
  uint8_t line_height;

  const Glyph* glyph(uint32_t codepoint) const;
};

// Draws UTF-8 text with the baseline at y. Codepoints the font lacks are
// skipped. Returns the pen x after the last glyph.
int draw_text(Framebuffer& fb, const Font& font, int x, int y, const char* text, bool black = true);

// Sum of advances, matching draw_text.
int text_width(const Font& font, const char* text);

// Draws text centred horizontally on cx.
void draw_text_centered(Framebuffer& fb, const Font& font, int cx, int y, const char* text,
                        bool black = true);

// Draws one glyph with its bitmap centred in a cell [x, x + cell_w).
// Used for tabular digits, so every digit sits in the same box.
void draw_glyph_centered(Framebuffer& fb, const Font& font, int x, int cell_w, int y,
                         uint32_t codepoint, bool black = true);

}  // namespace inkwake
